+  <main class="quiz-shell">
+    <h1>Computer Languages Quiz</h1>
+    <p class="intro">Choose all answers that apply for each question. Every question supports multiple selections.</p>
+
+    <form id="quiz-form">
+      <div class="form-field">
+        <p class="question-title">1. Which of these are commonly used for web development?</p>
+        <p class="help-text">Tip: more than one answer is correct, so select every language that fits.</p>
+        <div class="choices">
+          <label class="choice"><input type="checkbox" name="q1" value="JavaScript">JavaScript</label>
+          <label class="choice"><input type="checkbox" name="q1" value="Python">Python</label>
+          <label class="choice"><input type="checkbox" name="q1" value="HTML">HTML</label>
+          <label class="choice"><input type="checkbox" name="q1" value="CSS">CSS</label>
+        </div>
+      </div>
+
+      <div class="form-field">
+        <p class="question-title">2. Which of these are compiled programming languages?</p>
+        <div class="choices">
+          <label class="choice"><input type="checkbox" name="q2" value="C++">C++</label>
+          <label class="choice"><input type="checkbox" name="q2" value="Go">Go</label>
+          <label class="choice"><input type="checkbox" name="q2" value="Ruby">Ruby</label>
+          <label class="choice"><input type="checkbox" name="q2" value="Rust">Rust</label>
+        </div>
+      </div>
+
+      <div class="form-field">
+        <p class="question-title">3. Which of these are primarily used as query or data definition languages?</p>
+        <div class="choices">
+          <label class="choice"><input type="checkbox" name="q3" value="SQL">SQL</label>
+          <label class="choice"><input type="checkbox" name="q3" value="GraphQL">GraphQL</label>
+          <label class="choice"><input type="checkbox" name="q3" value="TypeScript">TypeScript</label>
+          <label class="choice"><input type="checkbox" name="q3" value="Bash">Bash</label>
+        </div>
+      </div>
+
+      <div class="actions">
+        <button type="submit">Submit Quiz</button>
+        <div id="result" aria-live="polite"></div>
+      </div>
+    </form>
+  </main>
+
+  <script>
+    const quizForm = document.getElementById("quiz-form");
+    const result = document.getElementById("result");
+
+    const answerKey = {
+      q1: ["JavaScript", "HTML", "CSS"],
+      q2: ["C++", "Go", "Rust"],
+      q3: ["SQL", "GraphQL"]
+    };
+
+    quizForm.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      const questionNames = Object.keys(answerKey);
+      const selections = {};
+
+      for (const name of questionNames) {
+        selections[name] = Array.from(
+          quizForm.querySelectorAll(`input[name="${name}"]:checked`)
+        ).map((input) => input.value);
+      }
+
+      const unanswered = questionNames.filter((name) => selections[name].length === 0);
+      if (unanswered.length > 0) {
+        result.className = "error";
+        result.textContent = "Please select at least one answer for every question.";
+        return;
+      }
+
+      let score = 0;
+      for (const name of questionNames) {
+        const expected = answerKey[name].slice().sort().join("|");
+        const actual = selections[name].slice().sort().join("|");
+        if (expected === actual) {
+          score += 1;
+        }
+      }
+
+      result.className = "success";
+      result.textContent = `You scored ${score} out of ${questionNames.length}.`;
+    });
+  </script>
+</body>
+</html>
*** End Patch
